-- Invoice Sales by Group Year = "Invoice Sales"
CREATE OR REPLACE TABLE "Invoice Sales by Group Year" ("Customer Group" Int32, "Versions" UInt8, "Years" UInt8, v Float64) ENGINE = Memory;
